using System;
using LittleLeo.Variables;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "BrightResonatorOmenData", menuName = "Data/Battle/Omens System/Omen Data/Hevelius/BrightResonator Omen Data")]
public class BrightResonatorOmenData : OmenData
{
	[Header("OnStartOfTurn Omen")]
	[SerializeField]
	private GameObjectReference playerGameObjectReference;

	[SerializeField]
	private LightShieldEffect lightShieldEffect;

	[SerializeField]
	private int endOfTurnPurificationAmount = 1;

	private Action omenCheckActivationAction;

	public override void Initialize(OmenInstance omenInstance)
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.BrightResonatorOmenAction = delegate
		{
			BrightResonatorPurification(startOfTurnActivation: true);
		};
		omenCheckActivationAction = delegate
		{
			if (playerGameObjectReference.value.GetComponent<UnitEffects>().IsEffectActiveGetAmount(lightShieldEffect) != 0)
			{
				ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.BrightResonatorEndOfTurnOmenAction = delegate
				{
					BrightResonatorPurification(startOfTurnActivation: false);
				};
			}
		};
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Add(omenCheckActivationAction);
		void BrightResonatorPurification(bool startOfTurnActivation)
		{
			int num = playerGameObjectReference.value.GetComponent<UnitEffects>().IsEffectActiveGetAmount(lightShieldEffect);
			if (num > 0)
			{
				omenInstance.EnqueueOmenFeedbackAndPlay();
				OmenLogic.ActivateOmen(BattleAction, num * (startOfTurnActivation ? ActionValue : endOfTurnPurificationAmount), null, null, CorruptionPurifyModifierEnum.NONE, playSFX: true);
			}
		}
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.BrightResonatorOmenAction = null;
		ReferenceSingleton<StartBattleStartEndTurnOmensHandler>.Instance.EndOfTurnOmenCheckActivateActions.Remove(omenCheckActivationAction);
	}

	public override string OmenConvertedDescription()
	{
		string localizedAtTheStartOfYourTurn = base.localizationManager.GetLocalizedAtTheStartOfYourTurn();
		string localizedAtTheEndOfYourTurn = base.localizationManager.GetLocalizedAtTheEndOfYourTurn();
		string text = base.OmenConvertedDescription();
		return localizedAtTheStartOfYourTurn + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + text + "\n" + localizedAtTheEndOfYourTurn + ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedSpace() + BattleAction.GetActionDescription(endOfTurnPurificationAmount);
	}
}
